window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0257e675ce25fc6e"]={"versions": [{"id": "FIG-0257e675ce25fc6e", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Metamodells für Kompositionen (<code>Composition</code>) im Kontext des AUTOSAR Technical Reports <em>Interaction with Behavioral Models</em>. Das Diagramm veranschaulicht die strukturelle Zuordnung von AUTOSAR-Metaklassen (<code>ARElement</code>, <code>ComponentType</code>, <code>CompositionType</code>, <code>ComponentPrototype</code>, <code>ConnectorPrototype</code>, <code>AssemblyConnectorPrototype</code>, <code>DelegationConnectorPrototype</code>) zu Werkzeug- bzw. Verhaltensmodellierungs-Konzepten des Pakets <code>BM Software-Component</code> (aus <code>Behavior Modeling</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Components::ComponentType</code> (Spezialisierung von <code>ARElement</code>): Basisklasse für Komponententypen.\n</li><li><code>Composition::CompositionType</code> (Stereotyp <code>«atpType»</code>): Spezialisiert <code>ComponentType</code>. Enthält per Komposition über die Rolle <code>+components</code> eine oder mehrere (<code>1..*</code>) Instanzen von <code>Composition::ComponentPrototype</code>. Zudem aggregiert <code>CompositionType</code> per Komposition über die Rolle <code>+connectors</code> beliebig viele (<code>*</code>) Verbinder vom Typ <code>Composition::ConnectorPrototype</code>.\n</li><li><code>Composition::ComponentPrototype</code> (Spezialisierung/Erfüllung von <code>Identifiable</code>): Repräsentiert die Instanziierung eines <code>ComponentType</code> innerhalb einer Komposition. Über die Relation <code>«isOfType»</code> verweist die Eigenschaft <code>+type</code> (Kardinalität <code>1</code>) auf den zugrundeliegenden <code>ComponentType</code> (Rolle auf der Gegenseite <code>*</code>).\n</li><li><code>Composition::ConnectorPrototype</code> (abstrakt/kursiv dargestellt, <code>Identifiable</code>): Basisklasse für Verbinder innerhalb einer Komposition (Rückreferenz auf <code>CompositionType</code> über Rolle <code>+composition</code>). Sie wird spezialisiert durch:\n<ul class=\"fig-list\"><li><code>Composition::DelegationConnectorPrototype</code>: Verbindet äußere Ports der Komposition mit internen Ports von Prototypen.\n</li><li><code>Composition::AssemblyConnectorPrototype</code>: Verbindet Ports zwischen internen <code>ComponentPrototype</code>-Instanzen.\n</li></ul>\n</li><li><code>BM Software-Component</code> (Paket aus <code>Behavior Modeling</code>): Steht über gestrichelte Import-Abhängigkeiten (<code>«import»</code> bzw. <code>«imports»</code> / Typbezug) in Beziehung zu <code>ComponentType</code>, <code>CompositionType</code>, <code>ComponentPrototype</code>, <code>ConnectorPrototype</code>, <code>AssemblyConnectorPrototype</code> und <code>DelegationConnectorPrototype</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Struktur- und Metamodell-Diagramm spezifiziert die Abbildung keinen zeitlichen Ablauf und keine dynamische Interaktionssequenz. Die Beziehungen definieren die statische Schachtelungshierarchie sowie die Mapping- bzw. Transformationspfade beim Im- und Export von Kompositionsstrukturen zwischen AUTOSAR-Beschreibungen und externen Verhaltensmodellierungswerkzeugen (Behavioral Modeling Tools, BMT).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für den Datenaustausch und Werkzeugbau ist wesentlich:</p>\n<ul class=\"fig-list\"><li>Werkzeuge zur Verhaltensmodellierung (BMT) müssen beim Import/Export von Kompositionen die Typ- und Instanz-Trennung (<code>ComponentType</code> vs. <code>ComponentPrototype</code>) sowie deren Konsistenz (<code>«isOfType»</code>) strikt wahren.\n</li><li>Für die Modellierung von Verbindungen müssen Werkzeuge zwischen <code>AssemblyConnectorPrototype</code> (Verbindung zwischen Komponentenprototypen innerhalb der Komposition) und <code>DelegationConnectorPrototype</code> (Delegation an die System- oder Kompositionsgrenze) unterscheiden.\n</li><li>Das Metamodell abstrahiert von Ausführungseigenschaften: Ein <code>AssemblyConnectorPrototype</code> spezifiziert lediglich die logische Verknüpfung der Ports, enthält jedoch selbst keine Ausführungssemantik (wie blockierend/nicht-blockierend, synchron/asynchron) oder Eigenschaften des Transportbusses. Derartige Details müssen bei Bedarf aus weiteren zugehörigen AUTOSAR-Modellelementen extrahiert oder ergänzt werden.\n</li></ul>"}, {"id": "FIG-34a98b08a63329b5", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Metamodells für Kompositionen (<code>Composition</code>) im Kontext des AUTOSAR Technical Reports <em>Interaction with Behavioral Models</em>. Das Diagramm veranschaulicht die strukturelle Zuordnung von AUTOSAR-Metaklassen (<code>ARElement</code>, <code>ComponentType</code>, <code>CompositionType</code>, <code>ComponentPrototype</code>, <code>ConnectorPrototype</code>, <code>AssemblyConnectorPrototype</code>, <code>DelegationConnectorPrototype</code>) zu Werkzeug- bzw. Verhaltensmodellierungs-Konzepten des Pakets <code>BM Software-Component</code> (aus <code>Behavior Modeling</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Components::ComponentType</code> (Spezialisierung von <code>ARElement</code>): Basisklasse für Komponententypen.\n</li><li><code>Composition::CompositionType</code> (Stereotyp <code>«atpType»</code>): Spezialisiert <code>ComponentType</code>. Enthält per Komposition über die Rolle <code>+components</code> eine oder mehrere (<code>1..*</code>) Instanzen von <code>Composition::ComponentPrototype</code>. Zudem aggregiert <code>CompositionType</code> per Komposition über die Rolle <code>+connectors</code> beliebig viele (<code>*</code>) Verbinder vom Typ <code>Composition::ConnectorPrototype</code>.\n</li><li><code>Composition::ComponentPrototype</code> (Spezialisierung/Erfüllung von <code>Identifiable</code>): Repräsentiert die Instanziierung eines <code>ComponentType</code> innerhalb einer Komposition. Über die Relation <code>«isOfType»</code> verweist die Eigenschaft <code>+type</code> (Kardinalität <code>1</code>) auf den zugrundeliegenden <code>ComponentType</code> (Rolle auf der Gegenseite <code>*</code>).\n</li><li><code>Composition::ConnectorPrototype</code> (abstrakt/kursiv dargestellt, <code>Identifiable</code>): Basisklasse für Verbinder innerhalb einer Komposition (Rückreferenz auf <code>CompositionType</code> über Rolle <code>+composition</code>). Sie wird spezialisiert durch:\n<ul class=\"fig-list\"><li><code>Composition::DelegationConnectorPrototype</code>: Verbindet äußere Ports der Komposition mit internen Ports von Prototypen.\n</li><li><code>Composition::AssemblyConnectorPrototype</code>: Verbindet Ports zwischen internen <code>ComponentPrototype</code>-Instanzen.\n</li></ul>\n</li><li><code>BM Software-Component</code> (Paket aus <code>Behavior Modeling</code>): Steht über gestrichelte Import-Abhängigkeiten (<code>«import»</code> bzw. <code>«imports»</code> / Typbezug) in Beziehung zu <code>ComponentType</code>, <code>CompositionType</code>, <code>ComponentPrototype</code>, <code>ConnectorPrototype</code>, <code>AssemblyConnectorPrototype</code> und <code>DelegationConnectorPrototype</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Struktur- und Metamodell-Diagramm spezifiziert die Abbildung keinen zeitlichen Ablauf und keine dynamische Interaktionssequenz. Die Beziehungen definieren die statische Schachtelungshierarchie sowie die Mapping- bzw. Transformationspfade beim Im- und Export von Kompositionsstrukturen zwischen AUTOSAR-Beschreibungen und externen Verhaltensmodellierungswerkzeugen (Behavioral Modeling Tools, BMT).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für den Datenaustausch und Werkzeugbau ist wesentlich:</p>\n<ul class=\"fig-list\"><li>Werkzeuge zur Verhaltensmodellierung (BMT) müssen beim Import/Export von Kompositionen die Typ- und Instanz-Trennung (<code>ComponentType</code> vs. <code>ComponentPrototype</code>) sowie deren Konsistenz (<code>«isOfType»</code>) strikt wahren.\n</li><li>Für die Modellierung von Verbindungen müssen Werkzeuge zwischen <code>AssemblyConnectorPrototype</code> (Verbindung zwischen Komponentenprototypen innerhalb der Komposition) und <code>DelegationConnectorPrototype</code> (Delegation an die System- oder Kompositionsgrenze) unterscheiden.\n</li><li>Das Metamodell abstrahiert von Ausführungseigenschaften: Ein <code>AssemblyConnectorPrototype</code> spezifiziert lediglich die logische Verknüpfung der Ports, enthält jedoch selbst keine Ausführungssemantik (wie blockierend/nicht-blockierend, synchron/asynchron) oder Eigenschaften des Transportbusses. Derartige Details müssen bei Bedarf aus weiteren zugehörigen AUTOSAR-Modellelementen extrahiert oder ergänzt werden.\n</li></ul>"}], "trans": [{"from": "FIG-0257e675ce25fc6e", "to": "FIG-34a98b08a63329b5", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
